{"filename":"page_session.js","content":"(function(){
  window.ForgeAI.registerPage('session', async function(ctx){
    const root = ctx.root;
    root.innerHTML = `
      <div class="page session-page">
        <h2>New Workout Session</h2>
        <form id="session-form">
          <div>
            <label for="workout-select">Workout</label>
            <select id="workout-select" required></select>
          </div>
          <div>
            <label for="date-input">Date</label>
            <input type="date" id="date-input" required />
          </div>
          <div>
            <label for="duration-input">Total Duration (minutes)</label>
            <input type="number" id="duration-input" min="1" required />
          </div>
          <div>
            <label for="calories-input">Calories Burned</label>
            <input type="number" id="calories-input" min="0" required />
          </div>
          <button type="submit">Save Session</button>
        </form>
        <div id="status" style="margin-top:10px;"></div>
      </div>`;
    const statusEl = root.querySelector('#status');
    async function loadWorkouts(){
      try {
        const resp = await ctx.api('/workouts', { method: 'GET' });
        if (!resp.success) { throw new Error('API error'); }
        const select = root.querySelector('#workout-select');
        resp.data.forEach(w => {
          const opt = document.createElement('option');
          opt.value = w.id;
          opt.textContent = w.title;
          select.appendChild(opt);
        });
      } catch (e) {
        statusEl.textContent = 'Error loading workouts.';
      }
    }
    await loadWorkouts();
    const form = root.querySelector('#session-form');
    form.addEventListener('submit', async (e) => {
      e.preventDefault();
      const data = {
        id: crypto.randomUUID(),
        workout_id: root.querySelector('#workout-select').value,
        date: root.querySelector('#date-input').value,
        total_duration_minutes: parseInt(root.querySelector('#duration-input').value, 10),
        calories_burned: parseInt(root.querySelector('#calories-input').value, 10)
      };
      try {
        const resp = await ctx.api('/sessions/new', { method: 'POST', json: data });
        if (resp.success) {
          statusEl.textContent = 'Session saved successfully.';
          form.reset();
        } else {
          statusEl.textContent = 'Failed to save session.';
        }
      } catch (err) {
        statusEl.textContent = 'Error saving session.';
      }
    });
  });
})();"}
